package com.android.tools.lint.checks

import com.android.tools.lint.detector.api.*
import org.jetbrains.uast.UCallExpression
import org.jetbrains.uast.UExpression
import org.jetbrains.uast.UReferenceExpression
import org.jetbrains.uast.resolveToUElement

class AccessibilityForceFocusDetector : Detector(), SourceCodeScanner {

    override fun getApplicableMethodNames(): List<String> = listOf(
        "sendAccessibilityEvent",
        "sendAccessibilityEventUnchecked",
        "performAction",
        "performAccessibilityAction"
    )

    override fun visitMethodCall(context: JavaContext, node: UCallExpression, visitor: JavaElementVisitor) {
        val methodName = node.methodName ?: return
        when (methodName) {
            "sendAccessibilityEvent", "sendAccessibilityEventUnchecked" -> {
                if (isAccessibilityEventType(context, node.valueArguments.getOrNull(0), "TYPE_VIEW_FOCUSED")) {
                    report(context, node)
                }
            }
            "performAction", "performAccessibilityAction" -> {
                if (isAccessibilityAction(context, node.valueArguments.getOrNull(0), "ACTION_ACCESSIBILITY_FOCUS")) {
                    report(context, node)
                }
            }
        }
    }

    private fun isAccessibilityEventType(context: JavaContext, arg: UExpression?, name: String): Boolean {
        if (arg == null) return false
        val resolved = arg.resolveToUElement() ?: return false
        // check field in android.view.accessibility.AccessibilityEvent
        val psi = resolved.javaPsi ?: return false
        return psi.containingClass?.qualifiedName == "android.view.accessibility.AccessibilityEvent"
                && psi.name == name
    }

    private fun isAccessibilityAction(context: JavaContext, arg: UExpression?, name: String): Boolean {
        if (arg == null) return false
        val resolved = arg.resolveToUElement() ?: return false
        val psi = resolved.javaPsi ?: return false
        return psi.containingClass?.qualifiedName == "android.view.accessibility.AccessibilityNodeInfo"
                && psi.name == name
    }

    private fun report(context: JavaContext, node: UCallExpression) {
        context.report(
            ISSUE,
            node,
            context.getLocation(node),
            "Forcing accessibility focus can interfere with screen readers"
        )
    }

    companion object {
        @JvmField
        val ISSUE = Issue.create(
            id = "AccessibilityFocus",
            briefDescription = "Forcing accessibility focus",
            explanation = """
                Forcing accessibility focus interferes with screen readers and gives an \
                inconsistent user experience, especially across apps.
            """.trimIndent(),
            category = Category.A11Y,
            priority = 3,
            severity = Severity.WARNING,
            implementation = Implementation(
                AccessibilityForceFocusDetector::class.java,
                Scope.JAVA_FILE_SCOPE
            )
        )
    }
}

